L000037	\title{Probing Dielectric Screening in van der Waals Heterostructures via Pressure-Tuned Exciton Rydberg Series}
L000038	
L000039	\author{Shalini Badola}
L000040	\affiliation{LNCMI, UPR 3228, CNRS, EMFL, Universit\'e Grenoble Alpes, 38000 Grenoble, France}
